const NOT_FOUND = Symbol();

type NotFound = typeof NOT_FOUND;

/**
 * @internal
 */
function useOther_withRoomContext<
  P extends JsonObject,
  U extends BaseUserMeta,
  T,
>(
  RoomContext: Context<OpaqueRoom | null>,
  connectionId: number,
  selector: (other: User<P, U>) => T,
  isEqual?: (prev: T, curr: T) => boolean
): T {
  const wrappedSelector = useCallback(
    (others: readonly User<P, U>[]) => {
      // TODO: Make this O(1) instead of O(n)?
      const other = others.find((other) => other.connectionId === connectionId);
      return other !== undefined ? selector(other) : NOT_FOUND;
    },
    [connectionId, selector]
  );

  const wrappedIsEqual = useCallback(
    (prev: T | NotFound, curr: T | NotFound): boolean => {
      if (prev === NOT_FOUND || curr === NOT_FOUND) {
        return prev === curr;
      }

      const eq = isEqual ?? Object.is;
      return eq(prev, curr);
    },
    [isEqual]
  );

  const other = useOthers_withRoomContext<P, U, T | NotFound>(
    RoomContext,
    wrappedSelector,
    wrappedIsEqual
  );
  if (other === NOT_FOUND) {
    throw new Error(
      `No such other user with connection id ${connectionId} exists`
    );
  }

  return other;
}

function useOther<P extends JsonObject, U extends BaseUserMeta, T>(
  connectionId: number,
  selector: (other: User<P, U>) => T,
  isEqual?: (prev: T, curr: T) => boolean
): T {
  return useOther_withRoomContext<P, U, T>(
    GlobalRoomContext,
    connectionId,
    selector,
    isEqual
  );
}

