/**
 * @private
 */
function useCreateRoomThread<TM extends BaseMetadata, CM extends BaseMetadata>(
  roomId: string
): (options: CreateThreadOptions<TM, CM>) => ThreadData<TM, CM> {
  const client = useClient();

  return useCallback(
    (options: CreateThreadOptions<TM, CM>): ThreadData<TM, CM> => {
      const body = options.body;
      const metadata = options.metadata ?? ({} as TM);
      const commentMetadata = options.commentMetadata ?? ({} as CM);
      const attachments = options.attachments;
      const visibility = options.visibility ?? "public";

      const threadId = createThreadId();
      const commentId = createCommentId();
      const createdAt = new Date();

      const newComment: CommentData<CM> = {
        id: commentId,
        threadId,
        roomId,
        createdAt,
        type: "comment",
        userId: getCurrentUserId(client),
        body,
        reactions: [],
        attachments: attachments ?? [],
        metadata: commentMetadata,
      };
      const newThread: ThreadData<TM, CM> = {
        id: threadId,
        type: "thread",
        createdAt,
        updatedAt: createdAt,
        roomId,
        metadata,
        comments: [newComment],
        resolved: false,
        visibility,
      };

      const { store, onMutationFailure } = getRoomExtrasForClient(client);
      const optimisticId = store.optimisticUpdates.add({
        type: "create-thread",
        thread: newThread,
        roomId,
      });

      const attachmentIds = attachments?.map((attachment) => attachment.id);

      client[kInternal].httpClient
        .createThread({
          roomId,
          threadId,
          commentId,
          body,
          visibility,
          metadata,
          commentMetadata,
          attachmentIds,
        })
        .then(
          (thread) => {
            // Replace the optimistic update by the real thing
            store.createThread(optimisticId, thread);
          },
          (err: Error) =>
            onMutationFailure(
              optimisticId,
              {
                type: "CREATE_THREAD_ERROR",
                roomId,
                threadId,
                commentId,
                body,
                visibility,
                metadata,
                commentMetadata,
              },
              err
            )
        );

      return newThread;
    },
    [client, roomId]
  );
}

