/**
 * Returns a function that edits a comment.
 *
 * @example
 * const editComment = useEditComment()
 * editComment({ threadId: "th_xxx", commentId: "cm_xxx", body: {} })
 */
function useEditComment<CM extends BaseMetadata>(): (
  options: EditCommentOptions<CM>
) => void {
  return useEditComment_withRoomContext<CM>(GlobalRoomContext);
}

/**
 * @private
 */
function useEditRoomComment<CM extends BaseMetadata>(
  roomId: string
): (options: EditCommentOptions<CM>) => void {
  const client = useClient();
  return useCallback(
    ({
      threadId,
      commentId,
      body,
      attachments,
      metadata,
    }: EditCommentOptions<CM>): void => {
      const editedAt = new Date();

      const { store, onMutationFailure } = getRoomExtrasForClient(client);
      const existing = store.outputs.threads.get().getEvenIfDeleted(threadId);

      if (existing === undefined) {
        console.warn(
          `Internal unexpected behavior. Cannot edit comment in thread "${threadId}" because the thread does not exist in the cache.`
        );
        return;
      }

      const comment = existing.comments.find(
        (comment) => comment.id === commentId
      );

      if (comment === undefined || comment.deletedAt !== undefined) {
        console.warn(
          `Internal unexpected behavior. Cannot edit comment "${commentId}" in thread "${threadId}" because the comment does not exist in the cache.`
        );
        return;
      }

      const updatedMetadata =
        metadata !== undefined
          ? {
              ...comment.metadata,
              ...metadata,
            }
          : comment.metadata;

      const optimisticId = store.optimisticUpdates.add({
        type: "edit-comment",
        comment: {
          ...comment,
          editedAt,
          body,
          attachments: attachments ?? [],
          metadata: updatedMetadata,
        },
      });

      const attachmentIds = attachments?.map((attachment) => attachment.id);

      client[kInternal].httpClient
        .editComment({
          roomId,
          threadId,
          commentId,
          body,
          attachmentIds,
          metadata,
          visibility: existing.visibility,
        })
        .then(
          (editedComment) => {
            // Replace the optimistic update by the real thing
            store.editComment(threadId, optimisticId, editedComment);
          },
          (err: Error) =>
            onMutationFailure(
              optimisticId,
              {
                type: "EDIT_COMMENT_ERROR",
                roomId,
                threadId,
                commentId,
                body,
                metadata: updatedMetadata,
              },
              err
            )
        );
    },
    [client, roomId]
  );
}

